  1	#include "rbtree.h"
  2	
  3	#include <stdlib.h>
  4	#include <string.h>
  5	
  6	/* ------------------------------------------------------------------------
  7	 * Allocation seam.
  8	 *
  9	 * Every allocation in this file goes through these two wrappers, never
 10	 * through malloc/free directly. HW2 replaces the bodies with a
 11	 * fault-injecting allocator; keeping the seam here means that change never
 12	 * has to touch the tree code itself.
 13	 * --------------------------------------------------------------------- */
 14	
 15	/* Blocks handed out by rb_malloc that rb_free has not taken back yet.
 16	 * Tests check this is 0 once the tree is destroyed; anything else is a leak,
 17	 * and the number is how many blocks leaked. */
 18	static size_t rb_live_allocs = 0;
 19	
 20	static void *rb_malloc(size_t n)
 21	{
 22	    void *p = malloc(n);
 23	    if (p != NULL) { // if memory is NULL, there is no memory or an issue with malloc, still want to allocate it.
 24	        rb_live_allocs++;
 25	    }
 26	    return p;
 27	}
 28	
 29	static void rb_free(void *p)
 30	{
 31	    if (p != NULL) {
 32	        rb_live_allocs--; // free(NULL) is legal and frees nothing, count would drop below the truth.
 33	    }
 34	    free(p);
 35	}
 36	
 37	/* Deliberately not in rbtree.h -- that header is frozen. Test files declare
 38	 * this themselves and the linker connects them. */
 39	size_t rb_debug_live_allocs(void)
 40	{
 41	    return rb_live_allocs;
 42	}
 43	
 44	/* A node is red or black. There is no third color -- deletion's "doubly
 45	 * black" is a way of counting, never a value stored in a node. */
 46	typedef enum { RB_RED, RB_BLACK } rb_color;
 47	
 48	struct rbnode {
 49	    char          *key;      /* our own copy of the caller's string; we free it */
 50	    void          *value;    /* the caller's pointer, stored as-is (not copied) */
 51	    rb_color       color;
 52	    struct rbnode *left;     /* NULL when there is no child */
 53	    struct rbnode *right;
 54	    struct rbnode *parent;   /* NULL only for the root */
 55	};
 56	
 57	struct rbtree {
 58	    struct rbnode   *root;       /* NULL when the tree is empty */
 59	    rb_value_free_fn value_free; /* NULL means the values are not ours to free */
 60	    size_t           count;      /* keys held, so rb_size answers instantly */
 61	};
 62	
 63	/* ------------------------------------------------------------------------
 64	 * Node lifetime. One node is TWO allocations: the struct, and a private copy
 65	 * of the key. Both are made here and both are freed in node_release, so the
 66	 * ownership rules live in exactly one place.
 67	 * --------------------------------------------------------------------- */
 68	
 69	/* Returns NULL if either allocation fails. On failure nothing is left
 70	 * allocated -- the caller never sees a half-built node. */
 71	static struct rbnode *node_alloc(const char *key, void *value)
 72	{
 73	    struct rbnode *n = rb_malloc(sizeof *n);
 74	    if (n == NULL) {
 75	        return NULL;
 76	    }
 77	
 78	    size_t len = strlen(key) + 1;           /* +1 for the '\0' terminator */
 79	    n->key = rb_malloc(len);
 80	    if (n->key == NULL) {
 81	        goto fail;                          /* unwind the first allocation */
 82	    }
 83	    memcpy(n->key, key, len);
 84	
 85	    n->value  = value;
 86	    n->color  = RB_RED;                     /* a new node is always red */
 87	    n->left   = NULL;
 88	    n->right  = NULL;
 89	    n->parent = NULL;
 90	    return n;
 91	
 92	fail:
 93	    rb_free(n);
 94	    return NULL;
 95	}
 96	
 97	/* Free one node: the value (only if the tree owns values), the key copy, and
 98	 * the struct. Does not touch left/right/parent -- unlinking is the caller's
 99	 * job, and this must never be called on a node still reachable from the tree. */
100	static void node_release(const rbtree_t *t, struct rbnode *n)
101	{
102	    if (t->value_free != NULL) {
103	        t->value_free(n->value);
104	    }
105	    rb_free(n->key);
106	    rb_free(n);
107	}
108	
109	/* rb_validate failure codes. 0 means every rule holds. Nonzero names the rule
110	 * that broke, which is far more useful in a failing test than a bare 1. */
111	enum {
112	    RB_OK              = 0,
113	    RB_BAD_ORDER       = 1,     /* in-order keys are not strictly increasing */
114	    RB_BAD_PARENT      = 2,     /* a child's parent pointer does not point back */
115	    RB_BAD_COUNT       = 3,     /* t->count disagrees with the real node count */
116	    RB_BAD_ROOT_PARENT = 4,     /* the root has a non-NULL parent */
117	    RB_BAD_ROOT_COLOR  = 5,     /* rule 2: the root is not black */
118	    RB_BAD_RED_RED     = 6,     /* rule 4: a red node has a red child */
119	    RB_BAD_BLACK_HEIGHT= 7,     /* rule 5: left and right black-heights differ */
120	};
121	
122	/* ------------------------------------------------------------------------
123	 * Balancing: rotations and the insert fixup.
124	 * --------------------------------------------------------------------- */
125	
126	/* A missing child counts as black (rule 3), so NULL is never red. Every
127	 * color test below goes through here so that rule lives in exactly one place. */
128	static bool is_red(const struct rbnode *n)
129	{
130	    return n != NULL && n->color == RB_RED;
131	}
132	
133	/* Left rotation at x. Precondition: x->right is a real node, never NULL.
134	 *
135	 *        x                  y
136	 *       / \                / \
137	 *      a   y      ==>      x   c
138	 *         / \            / \
139	 *        b   c          a   b
140	 *
141	 * Shape only: no key, value, or color changes, and nothing is allocated or
142	 * freed. The three-way reattach in the middle is what keeps t->root correct
143	 * when x was the root -- the caller never has to think about it. */
144	static void rotate_left(rbtree_t *t, struct rbnode *x)
145	{
146	    struct rbnode *y = x->right;
147	
148	    x->right = y->left;                     /* b moves across to x */
149	    if (y->left != NULL) {
150	        y->left->parent = x;
151	    }
152	
153	    y->parent = x->parent;                  /* y takes x's old place... */
154	    if (x->parent == NULL) {
155	        t->root = y;                        /* ...which was the root */
156	    } else if (x == x->parent->left) {
157	        x->parent->left = y;
158	    } else {
159	        x->parent->right = y;
160	    }
161	
162	    y->left = x;                            /* x tucks under y */
163	    x->parent = y;
164	}
165	
166	/* Right rotation at x: the mirror image. Precondition: x->left is not NULL. */
167	static void rotate_right(rbtree_t *t, struct rbnode *x)
168	{
169	    struct rbnode *y = x->left;
170	
171	    x->left = y->right;
172	    if (y->right != NULL) {
173	        y->right->parent = x;
174	    }
175	
176	    y->parent = x->parent;
177	    if (x->parent == NULL) {
178	        t->root = y;
179	    } else if (x == x->parent->right) {
180	        x->parent->right = y;
181	    } else {
182	        x->parent->left = y;
183	    }
184	
185	    y->right = x;
186	    x->parent = y;
187	}
188	
189	/* Restore the red-black rules after inserting z, which is red.
190	 *
191	 * Loop invariant: z is red; the root is black unless z is the root; and the
192	 * only rule that can be broken is rule 4 at exactly one spot -- z and its
193	 * parent both red. Rule 5 (equal black-heights on every path) holds the
194	 * whole time, because a red node adds nothing to any path's black count.
195	 *
196	 * Termination: the red-uncle case moves z up two levels without rotating, so
197	 * it can repeat at most height/2 times. The black-uncle cases rotate and
198	 * leave z's parent black, so the loop exits on the very next check. At most
199	 * two rotations in total. */
200	static void insert_fixup(rbtree_t *t, struct rbnode *z)
201	{
202	    while (is_red(z->parent)) {
203	        struct rbnode *p = z->parent;
204	        struct rbnode *g = p->parent;       /* p is red, so p is not the root */
205	
206	        if (p == g->left) {
207	            struct rbnode *u = g->right;    /* uncle; NULL counts as black */
208	
209	            if (is_red(u)) {
210	                /* Case 1: red uncle. Recolor and climb. No pointers move. */
211	                p->color = RB_BLACK;
212	                u->color = RB_BLACK;
213	                g->color = RB_RED;
214	                z = g;
215	            } else {
216	                if (z == p->right) {
217	                    /* Case 2: zig-zag. Straighten it, then fall into case 3.
218	                     * The rotation changes who is above whom, so re-read
219	                     * p and g afterward -- the old ones are stale. */
220	                    z = p;
221	                    rotate_left(t, z);
222	                    p = z->parent;
223	                    g = p->parent;
224	                }
225	                /* Case 3: straight line. One rotation at g fixes it, and
226	                 * p is now black, so the loop ends. */
227	                p->color = RB_BLACK;
228	                g->color = RB_RED;
229	                rotate_right(t, g);
230	            }
231	        } else {
232	            /* Mirror of the block above: every left and right swapped. */
233	            struct rbnode *u = g->left;
234	
235	            if (is_red(u)) {
236	                p->color = RB_BLACK;
237	                u->color = RB_BLACK;
238	                g->color = RB_RED;
239	                z = g;
240	            } else {
241	                if (z == p->left) {
242	                    z = p;
243	                    rotate_right(t, z);
244	                    p = z->parent;
245	                    g = p->parent;
246	                }
247	                p->color = RB_BLACK;
248	                g->color = RB_RED;
249	                rotate_left(t, g);
250	            }
251	        }
252	    }
253	
254	    t->root->color = RB_BLACK;              /* rule 2, unconditionally */
255	}
256	
257	rbtree_t *rb_create(rb_value_free_fn value_free)
258	{
259	    rbtree_t *t = rb_malloc(sizeof *t);
260	    if (t == NULL) {
261	        return NULL;
262	    }
263	    t->root = NULL;
264	    t->value_free = value_free;
265	    t->count = 0;
266	    return t;
267	}
268	
269	int rb_insert(rbtree_t *t, const char *key, void *value)
270	{
271	    struct rbnode *parent = NULL;
272	    struct rbnode *cur = t->root;
273	    int cmp = 0;
274	
275	    /* Invariant: key is not in any node above cur, and if it is in the tree
276	     * at all it is somewhere in the subtree rooted at cur. */
277	    while (cur != NULL) {
278	        cmp = strcmp(key, cur->key);
279	        if (cmp == 0) {
280	            /* Key already present: replace the value. The tree is the old
281	             * value's only owner, so free it first (if we own values). */
282	            if (t->value_free != NULL) {
283	                t->value_free(cur->value);
284	            }
285	            cur->value = value;
286	            return 0;                       /* count unchanged */
287	        }
288	        parent = cur;
289	        cur = (cmp < 0) ? cur->left : cur->right;
290	    }
291	
292	    /* Fell off the tree: cur is NULL and parent is the node to hang from.
293	     * cmp still holds the comparison against parent, so it tells us which side. */
294	    struct rbnode *n = node_alloc(key, value);
295	    if (n == NULL) {
296	        return -1;                          /* tree unchanged; caller keeps value */
297	    }
298	    n->parent = parent;
299	
300	    if (parent == NULL) {
301	        t->root = n;                        /* first node in an empty tree */
302	    } else if (cmp < 0) {
303	        parent->left = n;
304	    } else {
305	        parent->right = n;
306	    }
307	    t->count++;
308	
309	    insert_fixup(t, n);
310	    return 0;
311	}
312	
313	void *rb_find(const rbtree_t *t, const char *key)
314	{
315	    const struct rbnode *cur = t->root;
316	
317	    /* Invariant: if key is in the tree, it is in the subtree rooted at cur. */
318	    while (cur != NULL) {
319	        int cmp = strcmp(key, cur->key);
320	        if (cmp == 0) {
321	            return cur->value;
322	        }
323	        cur = (cmp < 0) ? cur->left : cur->right;
324	    }
325	    return NULL;
326	}
327	
328	int rb_delete(rbtree_t *t, const char *key)
329	{
330	    (void)t;
331	    (void)key;
332	    return -1;                  /* M2 */
333	}
334	
335	size_t rb_size(const rbtree_t *t)
336	{
337	    return (t == NULL) ? 0 : t->count;
338	}
339	
340	void rb_foreach(const rbtree_t *t,
341	                void (*fn)(const char *key, void *value, void *ctx),
342	                void *ctx)
343	{
344	    (void)t;
345	    (void)fn;
346	    (void)ctx;                  /* M1 */
347	}
348	
349	/* In-order walk of one subtree, checking every rule at once.
350	 *
351	 * The error travels in the RETURN VALUE; the data travels in the pointer
352	 * parameters. *prev is the last key seen (NULL before the first); every key
353	 * must be strictly greater. *count accumulates the real node count.
354	 * *black_height receives this subtree's black-height, but only on success.
355	 *
356	 * Every recursive call is followed by an early return if it failed, so the
357	 * first broken rule found -- however deep -- comes straight back up untouched. */
358	static int validate_subtree(const struct rbnode *n, const char **prev,
359	                            size_t *count, size_t *black_height)
360	{
361	    if (n == NULL) {
362	        *black_height = 1;                  /* the invisible black leaf */
363	        return RB_OK;
364	    }
365	
366	    /* Checks on this node first, before descending. */
367	    if (n->left != NULL && n->left->parent != n) {
368	        return RB_BAD_PARENT;
369	    }
370	    if (n->right != NULL && n->right->parent != n) {
371	        return RB_BAD_PARENT;
372	    }
373	    if (n->color == RB_RED && (is_red(n->left) || is_red(n->right))) {
374	        return RB_BAD_RED_RED;
375	    }
376	
377	    size_t left_bh = 0;
378	    int rc = validate_subtree(n->left, prev, count, &left_bh);
379	    if (rc != RB_OK) {
380	        return rc;                          /* early abort */
381	    }
382	
383	    if (*prev != NULL && strcmp(*prev, n->key) >= 0) {
384	        return RB_BAD_ORDER;
385	    }
386	    *prev = n->key;
387	    (*count)++;
388	
389	    size_t right_bh = 0;
390	    rc = validate_subtree(n->right, prev, count, &right_bh);
391	    if (rc != RB_OK) {
392	        return rc;                          /* early abort */
393	    }
394	
395	    /* Only compare once BOTH sides came back clean. */
396	    if (left_bh != right_bh) {
397	        return RB_BAD_BLACK_HEIGHT;
398	    }
399	
400	    *black_height = left_bh + (n->color == RB_BLACK ? 1 : 0);
401	    return RB_OK;
402	}
403	
404	int rb_validate(const rbtree_t *t)
405	{
406	    if (t->root != NULL) {
407	        if (t->root->parent != NULL) {
408	            return RB_BAD_ROOT_PARENT;
409	        }
410	        if (t->root->color != RB_BLACK) {
411	            return RB_BAD_ROOT_COLOR;
412	        }
413	    }
414	
415	    const char *prev = NULL;
416	    size_t count = 0;
417	    size_t black_height = 0;                /* received, not compared: every
418	                                               path below already agreed */
419	    int rc = validate_subtree(t->root, &prev, &count, &black_height);
420	    if (rc != RB_OK) {
421	        return rc;
422	    }
423	    if (count != t->count) {
424	        return RB_BAD_COUNT;
425	    }
426	    return RB_OK;
427	}
428	
429	/* Free a whole subtree, children before parent, so no freed node is ever
430	 * read again. Recursion is allowed in this assignment (HW2 takes it away). */
431	static void destroy_subtree(const rbtree_t *t, struct rbnode *n)
432	{
433	    if (n == NULL) {
434	        return;
435	    }
436	    destroy_subtree(t, n->left);
437	    destroy_subtree(t, n->right);
438	    node_release(t, n);
439	}
440	
441	void rb_destroy(rbtree_t *t)
442	{
443	    if (t == NULL) {
444	        return;                 /* the header promises NULL-safety */
445	    }
446	    destroy_subtree(t, t->root);
447	    rb_free(t);
448	}

