    24	/* The node struct and the color enum arrive in M1. For now the tree carries
    25	 * only what rb_create/rb_size/rb_destroy need. */
    26	struct rbtree {
    27	    rb_value_free_fn value_free;
    28	    size_t           count;
    29	};
    30	
    31	rbtree_t *rb_create(rb_value_free_fn value_free)
    32	{
    33	    rbtree_t *t = rb_malloc(sizeof *t);
    34	    if (t == NULL) {
    35	        return NULL;
    36	    }
    37	    t->value_free = value_free;
    38	    t->count = 0;
    39	    return t;
    40	}
