            CHECK(p != NULL && *p == (int)i, "%s: value behind %s is damaged",
                  c->name, c->keys[i]);
        }

        int v = rb_validate(t);
        CHECK(v == 0, "%s: validate code %d after deleting %s",
              c->name, v, c->victim);
    }

    rb_destroy(t);
    CHECK(values_freed == (int)c->n, "%s: %d of %zu values freed by the end",
          c->name, values_freed, c->n);
    expect_clean(c->name);
}

