27	/* A value_free that counts how many times it was called, so tests can prove
28	 * the tree freed exactly the values it was supposed to -- no more, no fewer. */
29	static int values_freed = 0;
30	static void counting_free(void *p)
31	{
32	    values_freed++;
33	    free(p);
34	}
