57	static void test_insert_and_find(void)
58	{
59	    /* Deliberately scrambled so the tree is not a straight line. */
60	    const char *keys[] = { "mango", "apple", "zebra", "kiwi", "banana",
61	                           "cherry", "peach" };
62	    const size_t n = sizeof keys / sizeof keys[0];
63	    int values[7] = { 10, 20, 30, 40, 50, 60, 70 };
64	
65	    rbtree_t *t = rb_create(NULL);      /* NULL: tree does not own values */
66	
67	    for (size_t i = 0; i < n; i++) {
68	        CHECK(rb_insert(t, keys[i], &values[i]) == 0,
69	              "insert %s failed", keys[i]);
70	        CHECK(rb_size(t) == i + 1,
71	              "after inserting %s size is %zu, expected %zu",
72	              keys[i], rb_size(t), i + 1);
73	        CHECK(rb_validate(t) == 0,
74	              "validate failed with code %d after inserting %s",
75	              rb_validate(t), keys[i]);
76	    }
77	
78	    /* Every key finds its own value, and the pointer is the same one. */
79	    for (size_t i = 0; i < n; i++) {
80	        CHECK(rb_find(t, keys[i]) == &values[i],
81	              "find %s returned wrong value", keys[i]);
82	    }
83	
84	    CHECK(rb_find(t, "missing") == NULL, "find of absent key not NULL");
85	    CHECK(rb_find(t, "") == NULL, "find of empty string not NULL");
86	    CHECK(rb_find(t, "appl") == NULL, "find of a prefix matched a key");
87	
88	    rb_destroy(t);
89	    expect_clean("test_insert_and_find");
90	}
