92	static void test_overwrite_frees_old_value(void)
93	{
94	    values_freed = 0;
95	    rbtree_t *t = rb_create(counting_free);    /* tree OWNS values now */
96	
97	    int *first = malloc(sizeof *first);
98	    int *second = malloc(sizeof *second);
99	    *first = 1;
100	    *second = 2;
101	
102	    CHECK(rb_insert(t, "key", first) == 0, "first insert failed");
103	    CHECK(rb_size(t) == 1, "size after first insert %zu", rb_size(t));
104	
105	    /* Same key again: value replaced, old value freed, size unchanged. */
106	    CHECK(rb_insert(t, "key", second) == 0, "overwrite failed");
107	    CHECK(rb_size(t) == 1, "size after overwrite %zu, expected 1", rb_size(t));
108	    CHECK(values_freed == 1, "expected old value freed once, got %d",
109	          values_freed);
110	    CHECK(rb_find(t, "key") == second, "find did not return the new value");
111	    CHECK(rb_validate(t) == 0, "validate failed after overwrite");
112	
113	    rb_destroy(t);
114	    CHECK(values_freed == 2, "expected 2 values freed total, got %d",
115	          values_freed);
116	    expect_clean("test_overwrite_frees_old_value");
117	}
