119	static void test_overwrite_same_pointer_is_noop(void)
120	{
121	    /* Re-inserting the SAME value pointer under the same key must not free
122	     * it: the tree already owns it, and freeing it would leave a dangling
123	     * pointer for rb_destroy to free a second time. Under ASan the old code
124	     * aborts with a double-free here; without ASan the counts catch it. */
125	    values_freed = 0;
126	    rbtree_t *t = rb_create(counting_free);
127	    CHECK(t != NULL, "rb_create returned NULL");
128	
129	    int *v = malloc(sizeof *v);
130	    CHECK(v != NULL, "malloc failed");
131	    *v = 7;
132	
133	    CHECK(rb_insert(t, "key", v) == 0, "first insert failed");
134	    CHECK(rb_insert(t, "key", v) == 0, "same-pointer re-insert failed");
135	    CHECK(values_freed == 0, "re-inserting the same pointer freed it (%d)",
136	          values_freed);
137	    CHECK(rb_find(t, "key") == v, "find no longer returns the value");
138	    CHECK(rb_size(t) == 1, "size %zu, expected 1", rb_size(t));
139	
140	    rb_destroy(t);
141	    CHECK(values_freed == 1, "expected exactly 1 free on destroy, got %d",
142	          values_freed);
143	    expect_clean("test_overwrite_same_pointer_is_noop");
144	}
