146	static void test_destroy_frees_every_value(void)
147	{
148	    values_freed = 0;
149	    rbtree_t *t = rb_create(counting_free);
150	    const int n = 25;
151	
152	    for (int i = 0; i < n; i++) {
153	        char key[16];
154	        snprintf(key, sizeof key, "k%02d", i);
155	        int *v = malloc(sizeof *v);
156	        *v = i;
157	        CHECK(rb_insert(t, key, v) == 0, "insert %s failed", key);
