160	    CHECK(rb_validate(t) == 0, "validate failed, code %d", rb_validate(t));
161	
162	    rb_destroy(t);
163	    CHECK(values_freed == n, "destroy freed %d values, expected %d",
164	          values_freed, n);
165	    expect_clean("test_destroy_frees_every_value");
166	}
