168	static void test_keys_are_copied(void)
169	{
170	    /* The caller's string buffer changes after insert. The tree must still
171	     * find the key by its ORIGINAL contents, proving it made its own copy. */
172	    rbtree_t *t = rb_create(NULL);
173	    char buf[16];
174	    int v = 99;
175	
176	    strcpy(buf, "original");
177	    CHECK(rb_insert(t, buf, &v) == 0, "insert failed");
178	
179	    strcpy(buf, "clobbered");            /* caller reuses the buffer */
180	
181	    CHECK(rb_find(t, "original") == &v, "tree lost the key after caller "
182	                                          "changed the buffer -- key not copied?");
183	    CHECK(rb_find(t, "clobbered") == NULL, "tree followed the caller's buffer");
184	
185	    rb_destroy(t);
186	    expect_clean("test_keys_are_copied");
187	}
